
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_10_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_10", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.903162245161253e+00, -4.806363111451605e+00, -4.670702998179276e+00, -4.482724064778969e+00, -4.226422138417518e+00, -3.884836292306931e+00, -3.443693422187603e+00, -2.897142972307776e+00, -2.253471648645967e+00, -1.551416146466057e+00, -9.461373164309084e-01, -6.647627808068605e-01, -6.214998727499943e-01, -5.293717003424019e-01, -3.688497428192651e-01, -2.102805253223634e-01, -9.456466205282925e-02, -3.147793619736729e-02, -6.758427233788353e-03, -7.602794465494312e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


